// Main application JavaScript

// Initialize when DOM is loaded
document.addEventListener('DOMContentLoaded', function() {
    console.log('App initialized');

    // Initialize sidebar navigation
    initializeSidebarNavigation();

    // Initialize sidebar toggle
    initializeSidebarToggle();

    // Test API button handler
    const testApiBtn = document.getElementById('testApiBtn');
    if (testApiBtn) {
        testApiBtn.addEventListener('click', testApiEndpoint);
    }

    // Form submission handler
    const dataForm = document.getElementById('dataForm');
    if (dataForm) {
        dataForm.addEventListener('submit', handleFormSubmit);
    }

    // Initialize DataTables
    initializeDataTables();
});


/**
 * Initialize sidebar navigation
 */
function initializeSidebarNavigation() {
    const sidebarLinks = document.querySelectorAll('.sidebar-link');

    sidebarLinks.forEach(link => {
        link.addEventListener('click', function(event) {
            event.preventDefault();

            // Remove active class from all links
            sidebarLinks.forEach(l => {
                l.classList.remove('active');
                l.removeAttribute('aria-current');
            });

            // Add active class to clicked link
            this.classList.add('active');
            this.setAttribute('aria-current', 'page');

            // Get the page name from data attribute
            const page = this.getAttribute('data-page');
            console.log(`Navigated to: ${page}`);

            // Close sidebar on mobile after selection
            if (window.innerWidth <= 768) {
                const sidebar = document.getElementById('sidebar');
                sidebar.classList.remove('show');
            }

            // Load page content
            loadPageContent(page);
        });
    });
}


/**
 * Initialize sidebar toggle button
 */
function initializeSidebarToggle() {
    const sidebarToggle = document.getElementById('sidebarToggle');
    const sidebar = document.getElementById('sidebar');

    if (sidebarToggle && sidebar) {
        sidebarToggle.addEventListener('click', function() {
            sidebar.classList.toggle('show');
            sidebar.classList.toggle('collapsed');
        });

        // Close sidebar when clicking outside on mobile
        document.addEventListener('click', function(event) {
            if (window.innerWidth <= 768) {
                const isClickInsideSidebar = sidebar.contains(event.target);
                const isClickOnToggle = sidebarToggle.contains(event.target);

                if (!isClickInsideSidebar && !isClickOnToggle && sidebar.classList.contains('show')) {
                    sidebar.classList.remove('show');
                }
            }
        });
    }
}


/**
 * Load content based on selected menu item
 */
function loadPageContent(page) {
    console.log(`Loading content for: ${page}`);

    // Hide all page content sections
    const pages = document.querySelectorAll('.page-content');
    pages.forEach(p => {
        p.classList.remove('active');
    });

    // Show the selected page
    const selectedPage = document.getElementById(`page-${page}`);
    if (selectedPage) {
        selectedPage.classList.add('active');

        // Smooth scroll to top of content
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
        console.error(`Page not found: page-${page}`);
    }

    // Optional: Load dynamic data for the page
    // Example: loadPageData(page);
}


/**
 * Load dynamic data for a specific page (optional)
 */
async function loadPageData(page) {
    try {
        const data = await apiCall(`/api/${page}`);
        console.log(`Data loaded for ${page}:`, data);
        // Update page content with loaded data
    } catch (error) {
        console.error(`Failed to load data for ${page}:`, error);
    }
}


/**
 * Initialize DataTables on all tables
 */
function initializeDataTables() {
    // Check if jQuery and DataTables are available
    if (typeof jQuery === 'undefined' || typeof jQuery.fn.DataTable === 'undefined') {
        console.error('DataTables or jQuery not loaded');
        return;
    }

    // Common DataTables configuration
    const commonConfig = {
        pageLength: 10,
        lengthMenu: [[5, 10, 25, 50, -1], [5, 10, 25, 50, "All"]],
        responsive: true,
        language: {
            search: "_INPUT_",
            searchPlaceholder: "Search...",
            lengthMenu: "Show _MENU_ entries",
            info: "Showing _START_ to _END_ of _TOTAL_ entries",
            infoEmpty: "Showing 0 to 0 of 0 entries",
            infoFiltered: "(filtered from _MAX_ total entries)",
            paginate: {
                first: "First",
                last: "Last",
                next: "Next",
                previous: "Previous"
            }
        },
        dom: '<"row"<"col-sm-12 col-md-6"l><"col-sm-12 col-md-6"f>>' +
             '<"row"<"col-sm-12"tr>>' +
             '<"row"<"col-sm-12 col-md-5"i><"col-sm-12 col-md-7"p>>'
    };

    // Initialize Recent Activity Table (Main page)
    if (jQuery('#recentActivityTable').length) {
        jQuery('#recentActivityTable').DataTable({
            ...commonConfig,
            order: [[0, 'desc']], // Sort by time descending
            columnDefs: [
                { orderable: false, targets: [3] } // Status column not sortable (badges)
            ]
        });
    }

    // Initialize Fabric List Table (Fabric page)
    if (jQuery('#fabricListTable').length) {
        jQuery('#fabricListTable').DataTable({
            ...commonConfig,
            order: [[0, 'asc']], // Sort by Fabric Name ascending
            columnDefs: [
                { orderable: false, targets: [5] } // Actions column not sortable
            ]
        });
    }

    // Initialize VRF Instances Table (VRF page)
    if (jQuery('#vrfInstancesTable').length) {
        jQuery('#vrfInstancesTable').DataTable({
            ...commonConfig,
            order: [[0, 'asc']], // Sort by VRF Name ascending
            columnDefs: [
                { orderable: false, targets: [4] } // Actions column not sortable
            ]
        });
    }

    // Initialize Interface List Table (Interfaces page)
    if (jQuery('#interfaceListTable').length) {
        jQuery('#interfaceListTable').DataTable({
            ...commonConfig,
            order: [[0, 'asc']], // Sort by Interface name ascending
            columnDefs: [
                { orderable: false, targets: [5] } // Actions column not sortable
            ]
        });
    }

    console.log('DataTables initialized');
}


/**
 * Test the API endpoint
 */
async function testApiEndpoint() {
    const responseDiv = document.getElementById('apiResponse');
    const responseContent = document.getElementById('apiResponseContent');

    try {
        const response = await fetch('/api/hello?name=User');
        const data = await response.json();

        responseContent.textContent = JSON.stringify(data, null, 2);
        responseDiv.style.display = 'block';

        // Smooth scroll to response
        responseDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    } catch (error) {
        console.error('API Error:', error);
        responseContent.textContent = JSON.stringify({
            error: 'Failed to fetch data',
            message: error.message
        }, null, 2);
        responseDiv.style.display = 'block';
    }
}


/**
 * Handle form submission
 */
async function handleFormSubmit(event) {
    event.preventDefault();

    const formResponse = document.getElementById('formResponse');
    const nameInput = document.getElementById('nameInput');
    const messageInput = document.getElementById('messageInput');

    const formData = {
        name: nameInput.value,
        message: messageInput.value,
        timestamp: new Date().toISOString()
    };

    try {
        const response = await fetch('/api/data', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(formData)
        });

        const data = await response.json();

        if (data.status === 'success') {
            formResponse.textContent = `✓ Success! Received: ${JSON.stringify(data.received)}`;
            formResponse.className = 'alert alert-success mt-3';
            formResponse.style.display = 'block';

            // Clear form
            nameInput.value = '';
            messageInput.value = '';
        } else {
            throw new Error('API returned error status');
        }
    } catch (error) {
        console.error('Form submission error:', error);
        formResponse.textContent = `✗ Error: ${error.message}`;
        formResponse.className = 'alert alert-danger mt-3';
        formResponse.style.display = 'block';
    }

    // Smooth scroll to response
    formResponse.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}


/**
 * Utility function to make API calls
 */
async function apiCall(endpoint, options = {}) {
    const defaultOptions = {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
        }
    };

    const config = { ...defaultOptions, ...options };

    try {
        const response = await fetch(endpoint, config);
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        return await response.json();
    } catch (error) {
        console.error('API call failed:', error);
        throw error;
    }
}


/**
 * Show toast notification (Bootstrap 5.3)
 */
function showToast(message, type = 'info') {
    // Create toast element
    const toastHtml = `
        <div class="toast align-items-center text-white bg-${type} border-0" role="alert" aria-live="assertive" aria-atomic="true">
            <div class="d-flex">
                <div class="toast-body">
                    ${message}
                </div>
                <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button>
            </div>
        </div>
    `;

    // You can append this to a toast container if you add one to the HTML
    console.log('Toast:', message);
}

